This keeps the neighbor test very direct. For each word removed from the queue, the code compares it with every unused word and counts how many characters differ. A word is a neighbor only when that count is exactly one.

It is easy to follow, but it is slower than generating possible replacements and checking a hash set. The input vector is only read, not changed.

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution{
public:
    int wordLadderLength(string startWord, string targetWord,
                         vector<string> &wordList) {
        bool targetExists = false;
        for (const string &word : wordList) {
            if (word == targetWord) {
                targetExists = true;
                break;
            }
        }
        if (!targetExists || startWord.size() != targetWord.size()) {
            return 0;
        }
        if (startWord == targetWord) {
            return 1;
        }

        queue<pair<string, int>> queue;
        queue.push({startWord, 1});
        vector<bool> used(wordList.size(), false);

        while (!queue.empty()) {
            auto current = queue.front();
            queue.pop();

            const string &word = current.first;
            int length = current.second;

            for (int index = 0; index < static_cast<int>(wordList.size()); ++index) {
                if (used[index] || wordList[index].size() != word.size()) {
                    continue;
                }

                int different = 0;
                for (int j = 0; j < static_cast<int>(word.size()); ++j) {
                    if (word[j] != wordList[index][j]) {
                        ++different;
                    }
                }

                if (different == 1) {
                    if (wordList[index] == targetWord) {
                        return length + 1;
                    }
                    used[index] = true;
                    queue.push({wordList[index], length + 1});
                }
            }
        }

        return 0;
    }
};
```

Time complexity: `O(N^2 * L)`, because every visited word may compare with all `N` list entries.

Space complexity: `O(N)` for the queue and the used array.

This uses BFS from both ends. One set starts at `startWord` and the other starts at `targetWord`. At each round, the smaller set is expanded, which usually creates fewer candidate words.

The two searches meet when a generated word is already in the opposite set. Both starting words count in the answer, so the initial length is `1`.

An important edge case is when the target is not in `wordList`; then no valid sequence can finish there.

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution{
public:
    int wordLadderLength(string startWord, string targetWord,
                         vector<string> &wordList) {
        if (startWord.size() != targetWord.size()) {
            return 0;
        }
        if (startWord == targetWord) {
            return 1;
        }

        unordered_set<string> words(wordList.begin(), wordList.end());
        if (!words.count(targetWord)) {
            return 0;
        }

        unordered_set<string> front = {startWord};
        unordered_set<string> back = {targetWord};
        words.erase(startWord);
        words.erase(targetWord);
        int length = 1;

        while (!front.empty() && !back.empty()) {
            if (front.size() > back.size()) {
                swap(front, back);
            }

            unordered_set<string> nextFront;
            for (const string &word : front) {
                string candidate = word;
                for (int i = 0; i < static_cast<int>(candidate.size()); ++i) {
                    char original = candidate[i];
                    for (char letter = 'a'; letter <= 'z'; ++letter) {
                        if (letter == original) {
                            continue;
                        }
                        candidate[i] = letter;

                        if (back.count(candidate)) {
                            return length + 1;
                        }
                        if (words.count(candidate)) {
                            words.erase(candidate);
                            nextFront.insert(candidate);
                        }
                    }
                    candidate[i] = original;
                }
            }

            front = move(nextFront);
            ++length;
        }

        return 0;
    }
};
```

Time complexity: roughly `O(N * L * 26)` candidate checks in the one-sided worst case, with the two-sided search often exploring fewer words.

Space complexity: `O(N * L)` for the word set and the two search frontiers.

Kept the neighbor generation inside BFS. For every position, the code tries letters from `a` through `z`, checks the new word in a `HashSet`, and removes it as soon as it enters the queue. Removing it immediately prevents duplicate paths from adding the same word again.

The returned count includes `startWord`. If there is no route, or the target is absent, the result is `0`.

Dry run on `hit`, `hot`, `dot`, `dog`, `cog` gives queue levels `1, 2, 3, 4, 5`, so the method returns `5`.

```java
import java.util.*;

class Solution {
    public int wordLadderLength(String startWord, String targetWord, List<String> wordList) {
        if (startWord.length() != targetWord.length()) {
            return 0;
        }

        Set<String> available = new HashSet<>(wordList);
        if (!available.contains(targetWord)) {
            return 0;
        }
        if (startWord.equals(targetWord)) {
            return 1;
        }

        Queue<String> queue = new ArrayDeque<>();
        queue.offer(startWord);
        available.remove(startWord);
        int length = 1;

        while (!queue.isEmpty()) {
            int levelSize = queue.size();

            for (int count = 0; count < levelSize; ++count) {
                String word = queue.poll();
                char[] letters = word.toCharArray();

                for (int i = 0; i < letters.length; ++i) {
                    char original = letters[i];
                    for (char letter = 'a'; letter <= 'z'; ++letter) {
                        if (letter == original) {
                            continue;
                        }

                        letters[i] = letter;
                        String nextWord = new String(letters);
                        if (nextWord.equals(targetWord)) {
                            return length + 1;
                        }
                        if (available.remove(nextWord)) {
                            queue.offer(nextWord);
                        }
                    }
                    letters[i] = original;
                }
            }
            ++length;
        }

        return 0;
    }
}
```

Time complexity: `O(N * L^2)` when creating each changed string is counted, with 26 treated as a constant.

Space complexity: `O(N * L)` for the set and queue.

I stored each word under patterns made by replacing one character with `*`. For example, `hot` creates `*ot`, `h*t`, and `ho*`. Words sharing a pattern are one change apart, so BFS can move through those groups without trying every possible letter.

The queue keeps the current word and its sequence length. A pattern is cleared after use so the same group is not scanned again.

Dry run for `hit` to `cog`:
`hit -> hot -> {dot, lot} -> {dog, log} -> cog`, so the answer is `5`.

```python
from collections import defaultdict, deque

class Solution:
    def wordLadderLength(self, startWord, targetWord, wordList):
        if len(startWord) != len(targetWord):
            return 0

        if targetWord not in wordList:
            return 0

        pattern_words = defaultdict(list)
        for word in wordList:
            for index in range(len(word)):
                pattern = word[:index] + "*" + word[index + 1:]
                pattern_words[pattern].append(word)

        queue = deque([(startWord, 1)])
        visited = {startWord}

        while queue:
            word, length = queue.popleft()
            if word == targetWord:
                return length

            for index in range(len(word)):
                pattern = word[:index] + "*" + word[index + 1:]
                for next_word in pattern_words[pattern]:
                    if next_word not in visited:
                        visited.add(next_word)
                        queue.append((next_word, length + 1))
                pattern_words[pattern].clear()

        return 0
```

Time complexity: `O(N * L^2)`, where `N` is the number of words and `L` is their length. Creating and hashing each pattern costs `O(L)`.

Space complexity: `O(N * L)` for the pattern map, queue, and visited set.

The word list is turned into a small pattern graph first. A pattern such as `h*t` points to every word that can be reached by changing the middle letter. BFS then follows these pattern groups.

Clearing a pattern's list after processing it matters. Without that line, the same group could be visited again from many words. If `targetWord` is missing, the method returns `0` immediately.

```java
import java.util.*;

class Solution {
    public int wordLadderLength(String startWord, String targetWord, List<String> wordList) {
        if (startWord.length() != targetWord.length() || !wordList.contains(targetWord)) {
            return 0;
        }
        if (startWord.equals(targetWord)) {
            return 1;
        }

        Map<String, List<String>> groups = new HashMap<>();
        for (String word : wordList) {
            for (int i = 0; i < word.length(); i++) {
                String pattern = word.substring(0, i) + '*' + word.substring(i + 1);
                groups.computeIfAbsent(pattern, key -> new ArrayList<>()).add(word);
            }
        }

        Queue<String> queue = new ArrayDeque<>();
        Queue<Integer> distances = new ArrayDeque<>();
        Set<String> visited = new HashSet<>();
        queue.offer(startWord);
        distances.offer(1);
        visited.add(startWord);

        while (!queue.isEmpty()) {
            String word = queue.poll();
            int distance = distances.poll();

            for (int i = 0; i < word.length(); i++) {
                String pattern = word.substring(0, i) + '*' + word.substring(i + 1);
                List<String> neighbors = groups.getOrDefault(pattern, Collections.emptyList());

                for (String nextWord : neighbors) {
                    if (nextWord.equals(targetWord)) {
                        return distance + 1;
                    }
                    if (visited.add(nextWord)) {
                        queue.offer(nextWord);
                        distances.offer(distance + 1);
                    }
                }
                groups.put(pattern, Collections.emptyList());
            }
        }

        return 0;
    }
}
```

For the usual sample, the queue starts with `(hit, 1)`, then adds `hot`, followed by `dot` and `lot`. The first target discovery gives the shortest sequence length.

Time complexity: `O(N * L^2)` for making the patterns and scanning their word groups.

Space complexity: `O(N * L)` for the pattern map and BFS data.

